51	// configureAccessReporter is the small part of the authenticated API used by
52	// onboarding. Keeping it narrow makes the state machine independently testable.
53	type configureAccessReporter interface {
54		ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
55	}
56	
57	// configureFlowDeps contains side effects used by the interactive configure
58	// flow. Tests can replace individual operations without a keyring, browser,
59	// GitHub CLI, or live control plane.
60	type configureFlowDeps struct {
61		resolveAuth  func(context.Context) (statusTarget, error)
62		fetchProfile profileFetcher
63		runLogin     func(context.Context, io.Writer, io.Writer) error
64		accessClient func(context.Context) (configureAccessReporter, error)
65		coreClient   func() (*coreapi.Client, error)
66		openURL      browserOpenFunc
67		githubAdmin  func(context.Context, string, string) (bool, error)
68		now          func() time.Time
69	}
70	
71	func newConfigureFlowDeps(insecure bool) configureFlowDeps {
72		return configureFlowDeps{
73			resolveAuth: func(ctx context.Context) (statusTarget, error) {
74				return resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
75			},
76			fetchProfile: defaultFetchProfile,
77			runLogin: func(ctx context.Context, outW, errW io.Writer) error {
78				cmd := newLoginCmd()
79				cmd.SetContext(ctx)
80				cmd.SetOut(outW)
81				cmd.SetErr(errW)
82				return cmd.RunE(cmd, nil)
83			},
84			accessClient: func(ctx context.Context) (configureAccessReporter, error) {
85				return NewAuthenticatedAPIClient(ctx, insecure)
86			},
87			coreClient:  coreapi.New,
88			openURL:     openBrowser,
89			githubAdmin: configureGitHubAdmin,
90			now:         time.Now,
91		}
92	}
