256	func configureOnboardingEnableOptions(opts EnableOptions) EnableOptions {
257		opts.Yes = true
258		opts.UseProjectSettings = true
259		opts.UseLocalSettings = false
260		opts.SuppressDoneMessage = true
261		opts.SuppressAdditionalSetup = true
262		// Logged-in onboarding does not ask a separate telemetry question. The
263		// documented default is applied without prompting; existing settings and
264		// ENTIRE_TELEMETRY_OPTOUT remain authoritative.
265		return opts
266	}
