393	func configureGitHubAdmin(ctx context.Context, owner, repo string) (bool, error) {
394		runner := execRunner{}
395		if !ghAvailable(ctx, runner) {
396			return false, errConfigureGHUnavailable
397		}
398		if !ghAuthenticated(ctx, runner) {
399			return false, errConfigureGHUnauthenticated
400		}
401		out, err := runner.Run(ctx, "gh", "api", "repos/"+owner+"/"+repo, "--jq", ".permissions.admin")
402		if err != nil {
403			return false, fmt.Errorf("check GitHub admin permission: %w", err)
404		}
405		admin, err := strconv.ParseBool(strings.TrimSpace(out))
406		if err != nil {
407			return false, fmt.Errorf("parse GitHub admin permission: %w", err)
408		}
409		return admin, nil
410	}
