439	func configureSuccessfulMirrorPlacements(selected []regionChoice, results []mirrorResult) []coreapi.ResolvedPlacement {
440		placements := make([]coreapi.ResolvedPlacement, 0, len(results))
441		for i, result := range results {
442			if i >= len(selected) || result.err != nil || result.cloneURL == "" {
443				continue
444			}
445			region := selected[i]
446			placements = append(placements, coreapi.ResolvedPlacement{
447				ClusterHost:  region.host,
448				Cell:         coreapi.NewOptString(region.slug),
449				Jurisdiction: coreapi.NewOptString(region.jurisdiction),
450			})
451		}
452		return placements
453	}
