707	// promptConfigureUpstreamAndAgents presents upstream, agents, and the dynamic
708	// save action as one persistent form. Save is always visible, while its actions
709	// change based on whether the choices require only local state or a commit and
710	// push. Arrow keys stay within the active section; Enter advances, while
711	// shift+tab revisits the previous section.
712	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint, branch string, protected, cleanWorktree, nonInteractive bool) (coreapi.ResolvedPlacement, []agent.Agent, string, bool, error) {
713		currentHost := configureCurrentUpstream(ctx, repoRoot)
714		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
715		if len(placements) == 0 {
716			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no upstreams available")
717		}
718	
719		// configurePlacementOrder puts the configured upstream first, so it is also
720		// the initial selection. If this repo has no Entire upstream yet, it falls
721		// back to the jurisdiction-preferred placement.
722		selectedHost := placements[0].ClusterHost
723		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
724		for _, placement := range placements {
725			placementByHost[placement.ClusterHost] = placement
726		}
727		upstreamOptions := func() []huh.Option[string] {
728			return configureUpstreamOptions(placements, selectedHost, currentHost)
729		}
730	
731		external.DiscoverAndRegisterAlways(ctx)
732		preselected := configureAgentPreselection(ctx)
733		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
734		if len(agentOptions) == 0 {
735			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("no agents with hook support available")
736		}
737		installedAgentNames := make([]string, 0)
738		for _, name := range GetAgentsWithHooksInstalled(ctx) {
739			installedAgentNames = append(installedAgentNames, string(name))
740		}
741		selectedAgentNames := make([]string, 0, len(preselected))
742		for _, option := range agentOptions {
743			if _, ok := preselected[types.AgentName(option.Value)]; ok {
744				selectedAgentNames = append(selectedAgentNames, option.Value)
745			}
746		}
747	
748		// huh's footer already documents navigation. Keep field descriptions for
749		// contextual information only, rather than repeating keyboard controls.
750		upstreamDescription := manageRegionsHint
751		upstreamControl := &configureUpstreamField{
752			value:       &selectedHost,
753			committed:   selectedHost,
754			highlighted: selectedHost,
755		}
756		upstreamControl.Select = huh.NewSelect[string]().
757			TitleFunc(func() string {
758				return configureQuestionTitle("Select your upstream", upstreamControl.focused)
759			}, &upstreamControl.focused).
760			Description(upstreamDescription).
761			Options(upstreamOptions()...).
762			Height(configureFieldHeight(len(placements), upstreamDescription)).
763			Value(&selectedHost)
764		upstreamControl.refresh = func() {
765			upstreamControl.Options(upstreamOptions()...)
766		}
767	
768		agentControl := newConfigureAgentControl(agentOptions, &selectedAgentNames, true)
769	
770		mirrorChanged := func() bool {
771			mirror, _ := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
772			return mirror
773		}
774		agentsChanged := func() bool {
775			_, agents := configureSelectionChanges(selectedHost, currentHost, selectedAgentNames, installedAgentNames)
776			return agents
777		}
778		requiresPush := func() bool {
779			return agentsChanged() && cleanWorktree && branch != ""
780		}
781		hasChanges := func() bool {
782			return mirrorChanged() || agentsChanged()
783		}
784	
785		previousHasChanges := hasChanges()
786		saveChoice := defaultConfigureSaveChoice(previousHasChanges, requiresPush(), protected)
787		saveControl := &configureSaveField{}
788		saveOptions := func() []huh.Option[string] {
789			return configureSaveOptions(branch, protected, requiresPush(), hasChanges(), saveChoice)
790		}
791		saveControl.Select = huh.NewSelect[string]().
792			TitleFunc(func() string {
793				return configureQuestionTitle("Save configuration", saveControl.focused)
794			}, &saveControl.focused).
795			Description(configureSaveDescription(branch, protected, requiresPush(), hasChanges())).
796			Options(saveOptions()...).
797			Height(configureFieldHeight(len(saveOptions()), configureSaveDescription(branch, protected, requiresPush(), hasChanges()))).
798			Value(&saveChoice)
799		refreshSave := func() {
800			changed := hasChanges()
801			options := saveOptions()
802			if changed != previousHasChanges || !configureOptionsContain(options, saveChoice) {
803				saveChoice = defaultConfigureSaveChoice(changed, requiresPush(), protected)
804				options = saveOptions()
805			}
806			previousHasChanges = changed
807			description := configureSaveDescription(branch, protected, requiresPush(), changed)
808			saveControl.Select.
809				Description(description).
810				Height(configureFieldHeight(len(options), description)).
811				Options(options...)
812		}
813		upstreamControl.layoutChanged = refreshSave
814		agentControl.selectionChanged = refreshSave
815		agentControl.showSave = func() bool { return true }
816	
817		if nonInteractive {
818			chosen, ok := placementByHost[selectedHost]
819			if !ok {
820				return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("default upstream is no longer available")
821			}
822			selectedAgents, err := configureSelectedAgents(selectedAgentNames)
823			if err != nil {
824				return coreapi.ResolvedPlacement{}, nil, "", false, err
825			}
826			return chosen, selectedAgents, configureNonInteractiveSaveChoice(hasChanges(), requiresPush(), protected), agentsChanged(), nil
827		}
828	
829		group := huh.NewGroup(upstreamControl, agentControl, saveControl)
830		form := newConfigureForm(group)
831		// Separate the form from the shell prompt or preceding onboarding status.
832		fmt.Fprintln(errW)
833		if err := form.RunWithContext(ctx); err != nil {
834			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
835				return coreapi.ResolvedPlacement{}, nil, "", false, cancelErr
836			}
837			return coreapi.ResolvedPlacement{}, nil, "", false, NewSilentError(errors.New("configure cancelled"))
838		}
839	
840		chosen, ok := placementByHost[selectedHost]
841		if !ok {
842			return coreapi.ResolvedPlacement{}, nil, "", false, errors.New("selected upstream is no longer available")
843		}
844		selectedAgents, err := configureSelectedAgents(selectedAgentNames)
845		if err != nil {
846			return coreapi.ResolvedPlacement{}, nil, "", false, err
847		}
848		if !hasChanges() && saveChoice != configureSaveCancel {
849			saveChoice = ""
850		}
851		return chosen, selectedAgents, saveChoice, agentsChanged(), nil
852	}
