1153	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1154		remotes, err := listGitRemotes(ctx, repoRoot)
1155		if err != nil {
1156			return "", err
1157		}
1158		current := ""
1159		if remotes[defaultMirrorRemote] {
1160			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1161			if err != nil {
1162				return "", fmt.Errorf("read origin remote URL: %w", err)
1163			}
1164		}
1165	
1166		forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1167		if err != nil {
1168			return "", err
1169		}
1170		preserve := ""
1171		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1172			if forgeRemote == "" {
1173				preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1174				forgeRemote = preserve
1175			}
1176		}
1177		if forgeRemote == "" {
1178			forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1179			forgeURL := configureGitHubForgeURL(ctx, owner, repo)
1180			if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1181				return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1182			}
1183			remotes[forgeRemote] = true
1184			fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1185		}
1186	
1187		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1188		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1189		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1190			return "", err
1191		}
1192		// Report the replaced URL and where it remains reachable. The returned
1193		// forgeRemote is deliberately separate from the mirror fetch remote: config
1194		// commits must land on GitHub, never in the one-way Entire mirror.
1195		reportMirrorRemotePlan(outW, errW, plan)
1196		return forgeRemote, nil
1197	}
1198	
1199	var configureGitHubProtocol = func(ctx context.Context) string { //nolint:gochecknoglobals // test seam for the user's gh protocol preference
1200		out, err := exec.CommandContext(ctx, "gh", "config", "get", "git_protocol", "--host", "github.com").Output()
1201		if err != nil {
1202			return "https"
1203		}
1204		protocol := strings.ToLower(strings.TrimSpace(string(out)))
1205		if protocol == configureGitProtocolSSH {
1206			return protocol
1207		}
1208		return "https"
1209	}
1210	
1211	func configureGitHubForgeURL(ctx context.Context, owner, repo string) string {
1212		if configureGitHubProtocol(ctx) == configureGitProtocolSSH {
1213			return fmt.Sprintf("git@github.com:%s/%s.git", owner, repo)
1214		}
1215		return fmt.Sprintf("https://github.com/%s/%s.git", owner, repo)
1216	}
1217	
1218	func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1219		names := make([]string, 0, len(remotes))
1220		for name := range remotes {
1221			if name != exclude {
1222				names = append(names, name)
1223			}
1224		}
1225		sort.SliceStable(names, func(i, j int) bool {
1226			priority := func(name string) int {
1227				switch name {
1228				case mirrorCloneProviderGitHub:
1229					return 0
1230				case defaultMirrorUpstreamRemote:
1231					return 1
1232				default:
1233					return 2
1234				}
1235			}
1236			if priority(names[i]) != priority(names[j]) {
1237				return priority(names[i]) < priority(names[j])
1238			}
1239			return names[i] < names[j]
1240		})
1241		for _, name := range names {
1242			raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1243			if err != nil {
1244				return "", fmt.Errorf("read remote %q URL: %w", name, err)
1245			}
1246			info, err := gitremote.ParseURL(raw)
1247			if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1248				strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1249				return name, nil
1250			}
1251		}
1252		return "", nil
1253	}
1254	
1255	func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
1256		for _, candidate := range candidates {
1257			if !remotes[candidate] {
1258				return candidate
1259			}
1260		}
1261		for i := 2; ; i++ {
1262			candidate := fmt.Sprintf("github-%d", i)
1263			if !remotes[candidate] {
1264				return candidate
1265			}
1266		}
1267	}
1268	
1269	// configureGitChanges returns porcelain status keyed by path. Its values retain
1270	// XY so callers can detect whether anything was already staged before the flow.
1271	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1272		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1273		if err != nil {
1274			return nil, fmt.Errorf("read git status: %w", err)
1275		}
1276		changes := make(map[string]string)
1277		for _, line := range strings.Split(out, "\n") {
1278			if len(line) < 4 {
1279				continue
1280			}
1281			path := strings.TrimSpace(line[3:])
1282			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1283				path = path[arrow+4:]
1284			}
1285			if path != "" {
1286				changes[path] = line[:2]
1287			}
1288		}
1289		return changes, nil
1290	}
1291	
1292	func newConfigureChanges(before, after map[string]string) []string {
1293		paths := make([]string, 0, len(after))
1294		for path := range after {
1295			if _, existed := before[path]; !existed {
1296				paths = append(paths, path)
1297			}
1298		}
1299		sort.Strings(paths)
1300		return paths
1301	}
1302	
1303	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1304		outW := cmd.OutOrStdout()
1305		if len(generated) == 0 {
1306			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1307			return nil
1308		}
1309		if len(before) != 0 {
1310			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1311			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1312			return nil
1313		}
1314	
1315		if branch == "" {
1316			return errors.New("cannot save configuration from a detached HEAD")
1317		}
1318		if protected && choice == configureSaveDirect {
1319			return fmt.Errorf("%s is protected; push to a new branch", branch)
1320		}
1321		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1322			return fmt.Errorf("unknown save choice %q", choice)
1323		}
1324		if forgeRemote == "" {
1325			return errors.New("no GitHub remote available for configuration push")
1326		}
1327	
1328		pushBranch := branch
1329		switchedBranch := false
1330		configurationCommitted := false
1331		if choice == configureSaveNewBranch {
1332			var err error
1333			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, forgeRemote, now)
1334			if err != nil {
1335				return err
1336			}
1337			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1338				return fmt.Errorf("create configuration branch: %w", err)
1339			}
1340			switchedBranch = true
1341			defer func() {
1342				if switchedBranch {
1343					// Best-effort fallback for failures after branch creation. Successful
1344					// paths restore explicitly below so an error can be returned.
1345					if restoreErr := restoreConfigureOriginalBranch(context.WithoutCancel(cmd.Context()), repoRoot, pushBranch, branch, generated, configurationCommitted); restoreErr != nil {
1346						fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not return configuration to original branch %q: %v\n", branch, restoreErr)
1347					}
1348				}
1349			}()
1350		}
1351	
1352		args := []string{"add", "--"}
1353		args = append(args, generated...)
1354		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1355			return fmt.Errorf("stage configuration: %w", err)
1356		}
1357		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1358			return fmt.Errorf("commit configuration: %w", err)
1359		}
1360		configurationCommitted = true
1361		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1362		if err != nil {
1363			return fmt.Errorf("read configuration commit: %w", err)
1364		}
1365		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1366		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1367			return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1368		}
1369		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1370		if choice == configureSaveNewBranch {
1371			if err := restoreConfigureOriginalBranch(cmd.Context(), repoRoot, pushBranch, branch, generated, configurationCommitted); err != nil {
1372				return err
1373			}
1374			switchedBranch = false
1375			fmt.Fprintf(outW, "✓ Returned to %s with configuration applied locally\n", branch)
1376			fmt.Fprintln(outW, "  Open a trail to merge it:")
1377			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1378		}
1379		return nil
1380	}
1381	
1382	func restoreConfigureOriginalBranch(ctx context.Context, repoRoot, sourceBranch, originalBranch string, generated []string, committed bool) error {
1383		if _, err := gitRunner(ctx, repoRoot, "switch", originalBranch); err != nil {
1384			return fmt.Errorf("return to original branch %q: %w", originalBranch, err)
1385		}
1386	
1387		var args []string
1388		if committed {
1389			// Switching to the original branch removes files introduced by the
1390			// configuration commit. Restore only the generated paths from the review
1391			// branch into the worktree, without touching the original branch's index,
1392			// so the repository remains configured while awaiting review.
1393			args = []string{"restore", "--source", sourceBranch, "--worktree", "--"}
1394		} else {
1395			// A failure before commit can carry staged generated files across the
1396			// switch. Unstage those paths while preserving their worktree contents.
1397			args = []string{"reset", "--"}
1398		}
1399		args = append(args, generated...)
1400		if _, err := gitRunner(ctx, repoRoot, args...); err != nil {
1401			return fmt.Errorf("restore configuration on original branch %q: %w", originalBranch, err)
1402		}
1403		return nil
1404	}
1405	
1406	func configureBranchHasNoUnpushedCommits(ctx context.Context, repoRoot string) bool {
1407		// @{u} is the branch's configured upstream before configure rewrites any
1408		// remotes. If it does not exist, we cannot prove a direct push is isolated to
1409		// the generated config commit, so only the new-branch action is safe.
1410		upstream, err := gitRunner(ctx, repoRoot, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
1411		if err != nil || upstream == "" {
1412			return false
1413		}
1414		ahead, err := gitRunner(ctx, repoRoot, "rev-list", "--count", upstream+"..HEAD")
1415		if err != nil {
1416			return false
1417		}
1418		count, err := strconv.Atoi(strings.TrimSpace(ahead))
1419		return err == nil && count == 0
1420	}
1421	
1422	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1423		// GitHub's branch `.protected` flag is true for *any* active ruleset rule.
1424		// A non-blocking rule such as Copilot code review therefore made ordinary
1425		// feature branches look push-protected. Inspect the effective rules instead
1426		// and only require a new branch for rules that can reject a direct update.
1427		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/rules/branches/"+url.PathEscape(branch)).Output()
1428		if err != nil {
1429			return false, fmt.Errorf("check GitHub branch rules: %w", err)
1430		}
1431		return configureRulesBlockDirectPush(out)
1432	}
1433	
1434	func configureRulesBlockDirectPush(raw []byte) (bool, error) {
1435		var rules []struct {
1436			Type string `json:"type"`
1437		}
1438		if err := json.Unmarshal(raw, &rules); err != nil {
1439			return false, fmt.Errorf("parse GitHub branch rules: %w", err)
1440		}
1441		for _, rule := range rules {
1442			switch rule.Type {
1443			case "pull_request", "required_status_checks", "required_deployments", "required_signatures", "merge_queue", "lock_branch", "update", "workflows":
1444				return true, nil
1445			}
1446		}
1447		return false, nil
1448	}
1449	
1450	func availableConfigureBranch(ctx context.Context, repoRoot, forgeRemote string, now func() time.Time) (string, error) {
1451		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1452		for _, candidate := range candidates {
1453			localExists, err := configureLocalBranchExists(ctx, repoRoot, candidate)
1454			if err != nil {
1455				return "", err
1456			}
1457			if localExists {
1458				continue
1459			}
1460			remoteExists, err := configureRemoteBranchExists(ctx, repoRoot, forgeRemote, candidate)
1461			if err != nil {
1462				return "", err
1463			}
1464			if !remoteExists {
1465				return candidate, nil
1466			}
1467		}
1468		return "", errors.New("could not choose an unused configuration branch name")
1469	}
1470	
1471	func configureLocalBranchExists(ctx context.Context, repoRoot, branch string) (bool, error) {
1472		_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+branch)
1473		if err == nil {
1474			return true, nil
1475		}
1476		var exitErr *exec.ExitError
1477		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1478			return false, nil
1479		}
1480		return false, fmt.Errorf("check local configuration branch %q: %w", branch, err)
1481	}
1482	
1483	func configureRemoteBranchExists(ctx context.Context, repoRoot, forgeRemote, branch string) (bool, error) {
1484		// Query the forge directly instead of relying on remote-tracking refs, which
1485		// may be stale or absent in a fresh clone. --exit-code returns 2 when no ref
1486		// matches, and any connectivity/auth failure is treated as an error rather
1487		// than risking reuse of another user's branch.
1488		_, err := gitRunner(ctx, repoRoot, "ls-remote", "--exit-code", "--heads", forgeRemote, "refs/heads/"+branch)
1489		if err == nil {
1490			return true, nil
1491		}
1492		var exitErr *exec.ExitError
1493		if errors.As(err, &exitErr) && exitErr.ExitCode() == 2 {
1494			return false, nil
1495		}
1496		return false, fmt.Errorf("check remote configuration branch %q on %q: %w", branch, forgeRemote, err)
1497	}
