131	// planMirrorRemote resolves what to write for a `mirror use` invocation.
132	// remotes is the set of already-configured remote names and currentURL the
133	// URL of the target remote ("" when it does not exist).
134	//
135	// upstream is the requested preserve-under name; it is honored only when the
136	// target remote is actually being repointed and the name is free. An occupied
137	// name is never clobbered — silently rewriting an existing `upstream` would be
138	// the one genuinely destructive thing this command could do — but it is recorded
139	// in preserveSkipped rather than dropped quietly, because a fork checkout
140	// (`origin` + `upstream` both already configured) hits that path by default and
141	// would otherwise see a clean ✓ while the replaced URL left git config for good.
142	func planMirrorRemote(remote, mirrorURL, currentURL, upstream string, remotes map[string]bool) mirrorRemotePlan {
143		plan := mirrorRemotePlan{remote: remote, mirrorURL: mirrorURL}
144		if !remotes[remote] {
145			plan.add = true
146			return plan
147		}
148		if strings.EqualFold(strings.TrimSpace(currentURL), mirrorURL) {
149			plan.noop = true
150			return plan
151		}
152		plan.replacedURL = currentURL
153		if upstream != "" {
154			// `remote` is known to exist in this branch, so an upstream naming it is
155			// "occupied" too and lands in the skipped case — no separate check needed.
156			if remotes[upstream] {
